 public static WorldBuilder Active; public List<RoadPath> Roads=new(); public List<MapLandmark> Landmarks=new(); public Vector3 SpawnPosition,FestivalCenter;public Quaternion SpawnRotation;public float WorldSize=3000;
 public const float WaterLevel=-3.5f;const float Sea=WaterLevel;const int Grid=300; WorldArt art;System.Random random;bool generated;int asphalt,edge,ivory,stone,roof,glass,wood,metal,coral,teal,gold,leaf,leafLight,bark,black,white,water,foam,pavers,grass,flowers;Transform content;Font signageFont;
