 static float S(float a,float b,float t)=>Mathf.SmoothStep(0,1,Mathf.InverseLerp(a,b,t));
 float R(float min,float max)=>Mathf.Lerp(min,max,(float)random.NextDouble());int I(int min,int max)=>random.Next(min,max);Color C(float r,float g,float b)=>new(r,g,b);
 public void Generate(){if(generated)return;generated=true;Active=this;random=new System.Random(78412);content=new GameObject("THE SUNWARD ISLES").transform;content.SetParent(transform,false);art=new WorldArt(content);Palette();Routes();Terrain();Ocean();BuildRoads();Festival();Town();LandmarksArt();DressRoads();Wilderness();CoastalPromenade();PlantedStreets();NaturalGroves();art.Flush();SpawnPosition=Roads[0].Position(0)+Vector3.up*.9f;SpawnRotation=Roads[0].Rotation(0);Debug.Log("Sunward island ready: "+Roads.Count+" routes / "+Mathf.RoundToInt((Roads[0].Length+Roads[1].Length+Roads[2].Length)/1000f)+" km of roads.");}
 void Palette(){asphalt=art.Mat("Basalt asphalt",C(.115f,.14f,.16f),.15f);edge=art.Mat("Pale crushed shell",C(.69f,.65f,.51f));ivory=art.Mat("Warm chalk plaster",C(.89f,.87f,.75f));stone=art.Mat("Honey limestone",C(.64f,.59f,.45f));roof=art.Mat("Sun baked clay",C(.57f,.22f,.105f));glass=art.Mat("Petrol glazing",C(.08f,.24f,.29f),.88f,.35f);wood=art.Mat("Oiled cedar",C(.26f,.14f,.08f));metal=art.Mat("Warm aluminium",C(.44f,.46f,.44f),.68f,.8f);coral=art.Mat("Sunward vermilion",C(.95f,.22f,.085f));teal=art.Mat("Festival lagoon",C(.07f,.56f,.51f));gold=art.Mat("Festival yellow",C(.99f,.72f,.16f));leaf=art.Mat("Coastal pine",C(.19f,.33f,.16f));leafLight=art.Mat("Sage leaf",C(.37f,.49f,.27f));bark=art.Mat("Palm bark",C(.37f,.27f,.14f));black=art.Mat("Graphite enamel",C(.035f,.065f,.073f),.28f);white=art.Mat("Road white",C(.93f,.91f,.73f),.2f);water=art.Mat("Deep azure",C(.045f,.29f,.39f),.87f,.32f);foam=art.Mat("Sea glass",C(.25f,.61f,.60f),.76f,.10f);pavers=art.Mat("Shellstone pavers",C(.70f,.72f,.65f));grass=art.Mat("Meadow sage",C(.35f,.47f,.24f));flowers=art.Mat("Coastal wildflower",C(.90f,.79f,.55f));var texture=new Texture2D(128,128,TextureFormat.RGB24,true){name="Hand laid shellstone",wrapMode=TextureWrapMode.Repeat};var pixels=new Color[128*128];for(int y=0;y<128;y++)for(int x=0;x<128;x++){int row=y/16,xx=(x+(row%2)*16)%32;float color=(xx<1||y%16<1)?.61f:.92f+Mathf.PerlinNoise(x*.15f,y*.15f)*.08f;pixels[y*128+x]=new Color(color,color,color);}texture.SetPixels(pixels);texture.Apply(true,true);art.Material(pavers).mainTexture=texture;}
 float BaseHeight(float x,float z){float a=Mathf.Atan2(z,x),radius=1090+65*Mathf.Sin(a*3+.4f)+48*Mathf.Cos(a*5-1);float d=Mathf.Sqrt(x*x+z*z*1.04f)/radius;float shore=1-S(.80f,1.045f,d);float ridge=137*Mathf.Exp(-((x+140)*(x+140)/190000f+(z-120)*(z-120)/175000f));float hills=19*Mathf.PerlinNoise((x+1340)*.0017f,(z+750)*.0017f)+4*Mathf.PerlinNoise(x*.007f+10,z*.007f+31);float h=-13+shore*(22+ridge+hills);float festival=Mathf.Max(Mathf.Abs(x+380)/100,Mathf.Abs(z+590)/90);h=Mathf.Lerp(13.4f,h,S(.58f,1.3f,festival));float town=Mathf.Max(Mathf.Abs(x-365)/250,Mathf.Abs(z+570)/170);h=Mathf.Lerp(13,h,S(.7f,1.35f,town));float south=-840+135*Mathf.Exp(-(x+540)*(x+540)/150000f)+60*Mathf.Exp(-(x-820)*(x-820)/100000f);float boulevard=S(-450,-570,z)*S(-900,-500,x)*(1-S(650,1000,x));h=Mathf.Lerp(h,Mathf.Min(h,13.4f),boulevard);h=Mathf.Lerp(Mathf.Min(h,Mathf.Lerp(-13,17,S(south-40,south+55,z))),h,S(south+45,south+125,z));return h;}
 void Routes(){Vector3 V(float x,float z)=>new(x,0,z);Add("SALTWIND COAST",18,new[]{V(-380,-600),V(40,-740),V(550,-650),V(820,-310),V(830,140),V(540,640),V(-100,850),V(-580,650),V(-850,260),V(-820,-230)});Add("THE HIGH MERIDIAN",14,new[]{V(820,-310),V(520,-265),V(275,-95),V(395,225),V(185,520),V(-140,410),V(-285,120),V(-100,-130),V(350,-370)});Add("LANTERN QUARTER",15,new[]{V(40,-740),V(315,-750),V(550,-650),V(650,-480),V(425,-403),V(135,-438),V(-60,-575)});for(int r=0;r<Roads.Count;r++){RoadPath road=Roads[r];for(int i=0;i<road.Points.Length-1;i++){var s=new Segment{A=road.Points[i],B=road.Points[i+1],Width=road.Width};int xa=Mathf.FloorToInt((Mathf.Min(s.A.x,s.B.x)-60)/64),xb=Mathf.FloorToInt((Mathf.Max(s.A.x,s.B.x)+60)/64),za=Mathf.FloorToInt((Mathf.Min(s.A.z,s.B.z)-60)/64),zb=Mathf.FloorToInt((Mathf.Max(s.A.z,s.B.z)+60)/64);for(int x=xa;x<=xb;x++)for(int z=za;z<=zb;z++){var key=new Vector2Int(x,z);if(!roadGrid.TryGetValue(key,out var list))roadGrid.Add(key,list=new List<Segment>());list.Add(s);}}}FestivalCenter=new Vector3(-380,13.4f,-570);}
 void Add(string name,float width,Vector3[] knots){var p=new RoadPath(name,knots,width,true,44);p.Length=0;for(int i=0;i<p.Points.Length;i++){p.Points[i].y=BaseHeight(p.Points[i].x,p.Points[i].z)+.16f;if(i>0){p.Length+=Vector3.Distance(p.Points[i-1],p.Points[i]);p.Distances[i]=p.Length;}}Roads.Add(p);}
 float Nearest(float x,float z,out float y,out float width){y=0;width=0;float best=999999;var key=new Vector2Int(Mathf.FloorToInt(x/64),Mathf.FloorToInt(z/64));if(!roadGrid.TryGetValue(key,out var list))return best;Vector2 p=new(x,z);foreach(var s in list){Vector2 a=new(s.A.x,s.A.z),v=new(s.B.x-s.A.x,s.B.z-s.A.z);float t=Mathf.Clamp01(Vector2.Dot(p-a,v)/v.sqrMagnitude),d=Vector2.Distance(p,a+v*t);if(d<best){best=d;y=Mathf.Lerp(s.A.y,s.B.y,t);width=s.Width;}}return best;}
 public float GroundHeight(float x,float z){float h=BaseHeight(x,z),d=Nearest(x,z,out float ry,out float width);return Mathf.Lerp(ry-.18f,h,S(width*.5f+17,width*.5f+49,d));}
