 void Terrain(){var tex=new Texture2D(768,768,TextureFormat.RGB24,true){name="Original island albedo",wrapMode=TextureWrapMode.Clamp};var pixels=new Color[768*768];for(int z=0;z<768;z++)for(int x=0;x<768;x++){float wx=(x/767f-.5f)*WorldSize,wz=(z/767f-.5f)*WorldSize,h=BaseHeight(wx,wz),n=Mathf.PerlinNoise(wx*.013f+8,wz*.013f+11),fine=Mathf.PerlinNoise(wx*.09f+77,wz*.09f+99);Color c=Color.Lerp(C(.37f,.46f,.28f),C(.56f,.61f,.42f),Mathf.Clamp01(n*.85f+(h-48)*.002f));c=Color.Lerp(c,C(.80f,.78f,.63f),1-S(1,11,h));c=Color.Lerp(c,C(.49f,.53f,.39f),S(80,160,h)*.4f);pixels[z*768+x]=c*Mathf.Lerp(.91f,1.08f,fine);}tex.SetPixels(pixels);tex.Apply(true,true);var mat=new Material(Shader.Find("Universal Render Pipeline/Lit")){name="Sunward island / terrain",color=Color.white,mainTexture=tex};mat.SetFloat("_Smoothness",.05f);int chunk=25;float step=WorldSize/Grid;for(int cz=0;cz<Grid;cz+=chunk)for(int cx=0;cx<Grid;cx+=chunk){int n=(chunk+1)*(chunk+1);var v=new Vector3[n];var uv=new Vector2[n];var tr=new int[chunk*chunk*6];for(int z=0;z<=chunk;z++)for(int x=0;x<=chunk;x++){float wx=(cx+x)*step-WorldSize*.5f,wz=(cz+z)*step-WorldSize*.5f;int k=z*(chunk+1)+x;v[k]=new(wx,GroundHeight(wx,wz),wz);uv[k]=new((cx+x)/(float)Grid,(cz+z)/(float)Grid);}int t=0;for(int z=0;z<chunk;z++)for(int x=0;x<chunk;x++){int k=z*(chunk+1)+x;tr[t++]=k;tr[t++]=k+chunk+1;tr[t++]=k+1;tr[t++]=k+1;tr[t++]=k+chunk+1;tr[t++]=k+chunk+2;}var mesh=new Mesh{name="Island ground "+cx+" "+cz};mesh.vertices=v;mesh.uv=uv;mesh.triangles=tr;mesh.RecalculateNormals();mesh.RecalculateBounds();var go=MeshObject(mesh,mat);go.AddComponent<MeshCollider>().sharedMesh=mesh;}}
 GameObject MeshObject(Mesh mesh,Material mat){var go=new GameObject(mesh.name);go.transform.SetParent(content,false);go.isStatic=true;go.AddComponent<MeshFilter>().sharedMesh=mesh;go.AddComponent<MeshRenderer>().sharedMaterial=mat;return go;}
 void Ocean(){var m=art.Material(water);var tx=new Texture2D(128,128,TextureFormat.RGBA32,true){name="Wind on water",wrapMode=TextureWrapMode.Repeat};var colors=new Color[128*128];for(int y=0;y<128;y++)for(int x=0;x<128;x++){float v=Mathf.Sin(x*.2945f+Mathf.Sin(y*.19635f)*2)*.5f+Mathf.Sin(y*.3436f+x*.09817f)*.3f;colors[y*128+x]=new(.048f+v*.006f,.29f+v*.015f,.37f+v*.017f,1);}tx.SetPixels(colors);tx.Apply(true,true);m.color=Color.white;m.mainTexture=tx;m.mainTextureScale=new(80,80);var mesh=new Mesh{name="The Pelagic Sea",vertices=new[]{new Vector3(-7500,Sea,-7500),new Vector3(-7500,Sea,7500),new Vector3(7500,Sea,7500),new Vector3(7500,Sea,-7500)},uv=new[]{Vector2.zero,Vector2.up,Vector2.one,Vector2.right},triangles=new[]{0,1,2,0,2,3}};mesh.RecalculateNormals();var go=MeshObject(mesh,m);go.GetComponent<MeshRenderer>().shadowCastingMode=ShadowCastingMode.Off;go.AddComponent<SunwardWaterMotion>();for(int i=0;i<320;i++){float a=i*Mathf.PI*2/320,b=(i+1)*Mathf.PI*2/320;Vector3 P(float angle,float offset){float lo=700,hi=1500;for(int j=0;j<14;j++){float mid=(lo+hi)*.5f;if(BaseHeight(Mathf.Cos(angle)*mid,Mathf.Sin(angle)*mid)>Sea)lo=mid;else hi=mid;}return new Vector3(Mathf.Cos(angle)*(lo+offset),Sea+.025f,Mathf.Sin(angle)*(lo+offset));}art.Quad(foam,P(a,-3),P(b,-3),P(b,55),P(a,55));if(i%7<4){Vector3 A=P(a,6),B=P(b,6);art.Beam(white,A,B,.17f);}}}
 void BuildRoads(){for(int r=0;r<Roads.Count;r++){var p=Roads[r];var verts=new List<Vector3>();var tr=new List<int>();for(int i=0;i<p.Points.Length;i++){Vector3 f=i==p.Points.Length-1?p.Points[1]-p.Points[0]:p.Points[Mathf.Min(i+1,p.Points.Length-1)]-p.Points[Mathf.Max(i-1,0)];Vector3 right=Vector3.Cross(Vector3.up,f.normalized).normalized;verts.Add(p.Points[i]-right*p.Width*.5f);verts.Add(p.Points[i]+right*p.Width*.5f);if(i>0){int k=i*2;tr.Add(k-2);tr.Add(k);tr.Add(k-1);tr.Add(k-1);tr.Add(k);tr.Add(k+1);Vector3 a=p.Points[i-1],b=p.Points[i],dir=(b-a).normalized,side=Vector3.Cross(Vector3.up,dir).normalized;for(int sign=-1;sign<=1;sign+=2){Vector3 inside=side*p.Width*.5f*sign,outside=side*(p.Width*.5f+4)*sign;if(sign<0)art.Quad(edge,a+outside-Vector3.up*.025f,b+outside-Vector3.up*.025f,b+inside-Vector3.up*.025f,a+inside-Vector3.up*.025f);else art.Quad(edge,a+inside-Vector3.up*.025f,b+inside-Vector3.up*.025f,b+outside-Vector3.up*.025f,a+outside-Vector3.up*.025f);MarkLine(a+side*(p.Width*.5f-.55f)*sign,b+side*(p.Width*.5f-.55f)*sign,.13f,white);}}}var mesh=new Mesh{name=p.Name+" / continuous driving surface"};mesh.SetVertices(verts);mesh.SetTriangles(tr,0);mesh.RecalculateNormals();mesh.RecalculateBounds();var go=MeshObject(mesh,art.Material(asphalt));go.AddComponent<MeshCollider>().sharedMesh=mesh;for(float d=8;d<p.Length;d+=14){p.Sample(d,out var a,out var f);p.Sample(Mathf.Min(d+5,p.Length-.1f),out var b,out _);Vector3 right=Vector3.Cross(Vector3.up,f).normalized;MarkLine(a-right*.17f,b-right*.17f,.13f,white);MarkLine(a+right*.17f,b+right*.17f,.13f,white);}for(float d=45;d<p.Length;d+=95){p.Sample(d,out var a,out var f);Vector3 right=Vector3.Cross(Vector3.up,f).normalized;for(int side=-1;side<=1;side+=2){Vector3 pos=a+right*(p.Width*.5f+1.5f)*side;art.Cylinder(ivory,pos,pos+Vector3.up*.85f,.10f,.08f,5);art.Box(side>0?coral:white,pos+Vector3.up*.68f,new(.13f,.12f,.13f),Quaternion.LookRotation(f));}}}}
