 void Festival(){Vector3 c=FestivalCenter;art.Box(edge,new(-380,13.19f,-556),new(168,.4f,93),Quaternion.identity);for(int i=0;i<7;i++)art.Box(i%2==0?ivory:stone,new(-450+i*24,13.425f,-556),new(.2f,.015f,89),Quaternion.identity);Vector3 P(float x,float y,float z)=>new Vector3(-380+x,13.4f+y,-555+z);art.Box(black,P(0,1,30),new(56,2,22),Quaternion.identity);art.Box(teal,P(0,7,41),new(53,10,.5f),Quaternion.identity);art.Box(coral,P(0,10,40.4f),new(50,.4f,.4f),Quaternion.identity);art.Box(black,P(0,6.2f,40.5f),new(35,7,.35f),Quaternion.identity);Text("S U N W A R D",P(0,7.4f,40.1f),Quaternion.identity,5.7f,Color.white);Text("F R E E D O M   I N   M O T I O N",P(0,4.6f,40.0f),Quaternion.identity,1.4f,new Color(.98f,.76f,.34f));for(int s=-1;s<=1;s+=2){art.Box(black,P(s*24,4,25),new(3.5f,7,3.3f),Quaternion.identity);for(int j=0;j<3;j++)art.Cylinder(metal,P(s*24,2+j*2,23.2f),P(s*24,2+j*2,23.05f),.72f,.72f,12);art.Cylinder(ivory,P(s*28,0,19),P(s*28,14,19),.25f,.18f,8);}for(int i=0;i<20;i++){float x=-32+i*3.4f,z=i%2==0?12:40;Vector3 a=P(x,14,z),b=P(x+10,10,z==12?40:12);art.Beam(white,a,b,.085f);}art.Quad(ivory,P(-30,14,15),P(-30,13,44),P(30,13,44),P(30,14,15));art.Quad(ivory,P(30,14,15),P(30,13,44),P(-30,13,44),P(-30,14,15));for(int i=0;i<9;i++){float x=-74+i*18;Flag(P(x,0,-26),i%3==0?gold:i%3==1?coral:teal,8,Quaternion.Euler(0,90,0));}for(int i=0;i<4;i++){Vector3 p=P(-65+i*42,0,-4);if(i==1||i==2)continue;Canopy(p,Quaternion.identity,13,11,i==0?coral:teal);art.Box(ivory,p+new Vector3(0,1.1f,0),new(10,2.2f,2),Quaternion.identity);Text(i==0?"THE GARAGE":"DRIVE CLUB",p+new Vector3(0,4.0f,-5.6f),Quaternion.identity,1.4f,Color.white);}for(int i=0;i<12;i++){Vector3 p=P(R(-68,68),0,R(-10,11));Person(p,I(0,3));}for(int i=0;i<4;i++){Palm(P(-81+i*54,0,43),R(10,13));art.Cylinder(ivory,P(-81+i*54,0,43),P(-81+i*54,.8f,43),2.4f,2.4f,12);}RoadPath road=Roads[0];road.Sample(36,out var gate,out var forward);Quaternion q=Quaternion.LookRotation(forward);Vector3 right=q*Vector3.right;for(int s=-1;s<=1;s+=2){art.Box(coral,gate+right*12*s+Vector3.up*4,new(1.1f,8,1.1f),q);art.Box(black,gate+right*12*s+Vector3.up*.65f,new(2.4f,1.3f,2.4f),q);}art.Box(coral,gate+Vector3.up*8.1f,new(25,1.4f,1),q);Text("S U N W A R D",gate+Vector3.up*8.1f-forward*.54f,q,1.8f,Color.white);for(int i=0;i<20;i++){Vector3 a=road.Position(22)+right*(-9+i*.9f)+Vector3.up*.029f;art.Box(i%2==0?white:black,a,new(.9f,.012f,1.6f),q);}Landmarks.Add(new("SUNWARD FESTIVAL","FESTIVAL",c,new Color(1,.33f,.1f)));}
 void Flag(Vector3 p,int m,float h,Quaternion q){art.Cylinder(metal,p,p+Vector3.up*h,.045f,.04f,5);Vector3 P(float x,float y,float z)=>p+q*new Vector3(x,y,z);for(int i=0;i<7;i++){float a=i/7f,b=(i+1)/7f;Vector3 A=P(.12f,h-a*h*.62f,Mathf.Sin(a*5)*.23f),B=P(.12f,h-b*h*.62f,Mathf.Sin(b*5)*.23f),C=P(1.3f-b*.35f,h-b*h*.62f,Mathf.Sin(b*5+1)*.3f),D=P(1.3f-a*.35f,h-a*h*.62f,Mathf.Sin(a*5+1)*.3f);art.Quad(m,A,B,C,D);art.Quad(m,D,C,B,A);}}
 void Canopy(Vector3 p,Quaternion q,float w,float d,int m){Vector3 P(float x,float y,float z)=>p+q*new Vector3(x,y,z);for(int a=-1;a<=1;a+=2)for(int b=-1;b<=1;b+=2)art.Cylinder(ivory,P(a*w*.5f,0,b*d*.5f),P(a*w*.5f,4.2f,b*d*.5f),.08f,.06f,6);for(int a=-1;a<=1;a+=2){art.Tri(m,P(-w*.5f,4.2f,a*d*.5f),P(w*.5f,4.2f,a*d*.5f),P(0,7,0));art.Tri(m,P(w*.5f,4.2f,a*d*.5f),P(-w*.5f,4.2f,a*d*.5f),P(0,7,0));art.Tri(m,P(a*w*.5f,4.2f,-d*.5f),P(a*w*.5f,4.2f,d*.5f),P(0,7,0));art.Tri(m,P(a*w*.5f,4.2f,d*.5f),P(a*w*.5f,4.2f,-d*.5f),P(0,7,0));}}
