 void DressRoads(){for(int r=0;r<Roads.Count;r++){RoadPath road=Roads[r];for(float d=90;d<road.Length;d+=r==0?48:75){road.Sample(d,out var p,out var f);Vector3 side=Vector3.Cross(Vector3.up,f).normalized;for(int sign=-1;sign<=1;sign+=2){Vector3 pos=p+side*(road.Width*.5f+R(7,13))*sign;pos.y=GroundHeight(pos.x,pos.z);if(NearOccupied(pos,14)||(pos-FestivalCenter).sqrMagnitude<10000||Nearest(pos.x,pos.z,out _,out float w)<w*.5f+4)continue;if(r==0&&p.z<0||r==2)Palm(pos,R(8,13));else if(random.NextDouble()>.3)Pine(pos,R(8,14));if(r==0&&d%144<48)Lamp(p+side*(road.Width*.5f+2.9f)*sign,Quaternion.LookRotation(f*sign),true);}if(r==1&&d%150<75){for(int sign=-1;sign<=1;sign+=2){float terrain=BaseHeight((p+side*20*sign).x,(p+side*20*sign).z);if(terrain>p.y+2)continue;for(float t=0;t<45;t+=5){road.Sample(d+t,out var a,out var af);Vector3 sr=Vector3.Cross(Vector3.up,af).normalized;Vector3 post=a+sr*(road.Width*.5f+2)*sign;art.Cylinder(metal,post,post+Vector3.up*.85f,.07f,.06f,5);road.Sample(d+t+5,out var b,out var bf);Vector3 br=Vector3.Cross(Vector3.up,bf).normalized;art.Beam(metal,post+Vector3.up*.70f,b+br*(road.Width*.5f+2)*sign+Vector3.up*.70f,.17f,.10f);}}}if(d%600<50){Vector3 sign=p+side*(road.Width*.5f+4);Quaternion q=Quaternion.LookRotation(f);art.Cylinder(metal,sign,sign+Vector3.up*4,.09f,.09f,6);art.Box(teal,sign+Vector3.up*4,new(5,1.4f,.14f),q);Text(r==0?"SALTWIND  /  COAST":r==1?"THE MERIDIAN  ↑":"LANTERN QUARTER",sign+Vector3.up*4-f*.085f,q,.44f,Color.white);}}}}
 void Palm(Vector3 p,float h){Vector3 top=p+new Vector3(h*.10f,h,0);for(int i=0;i<5;i++){float a=i/5f,b=(i+1)/5f;Vector3 A=p+new Vector3(h*.1f*a*a,h*a,0),B=p+new Vector3(h*.1f*b*b,h*b,0);art.Cylinder(bark,A,B,.22f*(1-a*.50f),.22f*(1-b*.5f),7);}float angle=R(0,360);for(int i=0;i<9;i++){float a=(angle+i*40)*Mathf.Deg2Rad;Vector3 dir=new(Mathf.Cos(a),0,Mathf.Sin(a)),side=Vector3.Cross(Vector3.up,dir);float length=R(4,5.8f);for(int j=0;j<6;j++){float u=j/6f,v=(j+1)/6f;Vector3 A=top+dir*(u*length)+Vector3.up*(Mathf.Sin(u*Mathf.PI)*1.4f-u*u*2.4f),B=top+dir*(v*length)+Vector3.up*(Mathf.Sin(v*Mathf.PI)*1.4f-v*v*2.4f);float wa=Mathf.Sin(u*Mathf.PI)*.64f,wb=Mathf.Sin(v*Mathf.PI)*.64f;art.Quad(i%3==0?leafLight:leaf,A,A+side*wa-Vector3.up*.17f,B+side*wb-Vector3.up*.17f,B);art.Quad(i%3==0?leafLight:leaf,B,B-side*wb-Vector3.up*.17f,A-side*wa-Vector3.up*.17f,A);art.Quad(leaf,B,A,A+side*wa-Vector3.up*.17f,B+side*wb-Vector3.up*.17f);art.Quad(leaf,A,B,B-side*wb-Vector3.up*.17f,A-side*wa-Vector3.up*.17f);}}art.Rock(bark,top,new(.45f,.38f,.40f),R(0,99),2,7);}
 void Pine(Vector3 p,float h){art.Cylinder(bark,p,p+Vector3.up*h*.78f,.30f,.12f,7);for(int i=0;i<3;i++){float a=i*Mathf.PI*2/3;Vector3 branch=p+new Vector3(Mathf.Cos(a)*h*.17f,h*.79f,Mathf.Sin(a)*h*.17f);art.Beam(bark,p+Vector3.up*h*.53f,branch,.16f);art.Rock(i==0?leafLight:leaf,branch,new(h*.31f,h*.17f,h*.29f),R(0,200),3,9);}art.Rock(leaf,p+Vector3.up*h*.89f,new(h*.3f,h*.18f,h*.3f),R(0,200),3,9);}
 void CoastalPromenade(){RoadPath road=Roads[0];for(float d=0;d<480;d+=7){road.Sample(d,out var a,out var af);road.Sample(d+7,out var b,out var bf);Vector3 ar=Vector3.Cross(Vector3.up,af).normalized,br=Vector3.Cross(Vector3.up,bf).normalized;for(int sign=-1;sign<=1;sign+=2){Vector3 A=a+ar*(road.Width*.5f+.2f)*sign+Vector3.up*.04f,B=b+br*(road.Width*.5f+.2f)*sign+Vector3.up*.04f,C=b+br*(road.Width*.5f+5)*sign+Vector3.up*.04f,D=a+ar*(road.Width*.5f+5)*sign+Vector3.up*.04f;if(sign>0)art.Surface(pavers,A,B,C,D);else art.Surface(pavers,D,C,B,A);art.Beam(ivory,D+Vector3.up*.07f,C+Vector3.up*.07f,.24f,.20f);}}for(float d=9;d<480;d+=26){road.Sample(d,out var p,out var f);Vector3 right=Vector3.Cross(Vector3.up,f).normalized;for(int sign=-1;sign<=1;sign+=2){if(d<55&&sign<0)continue;Vector3 tree=p+right*18*sign;tree.y=GroundHeight(tree.x,tree.z);Palm(tree,R(9,12));art.Cylinder(ivory,tree-Vector3.up*.05f,tree+Vector3.up*.55f,1.8f,1.8f,12);art.Cylinder(grass,tree+Vector3.up*.56f,tree+Vector3.up*.57f,1.54f,1.54f,12);for(int k=0;k<5;k++){float a=k*Mathf.PI*.4f;Shrub(tree+new Vector3(Mathf.Cos(a)*1.15f,.55f,Mathf.Sin(a)*1.15f),.65f,k%2==0);}}if(d%78<26){Vector3 bp=p+right*13;bp.y=GroundHeight(bp.x,bp.z);Bench(bp,Quaternion.LookRotation(f));}for(int j=0;j<7;j++){Vector3 q=p+right*R(20,29)+f*R(-10,10);q.y=GroundHeight(q.x,q.z);if(q.y>1)Shrub(q,R(.6f,1.7f),j%4==0);}}for(int k=0;k<3;k++){float d=65+k*42;road.Sample(d,out var p,out var f);Vector3 right=Vector3.Cross(Vector3.up,f).normalized;Vector3 site=p-right*29;site.y=GroundHeight(site.x,site.z);Canopy(site,Quaternion.LookRotation(f),10,9,k%2==0?teal:coral);art.Box(wood,site+Vector3.up*1,new(7,2,2),Quaternion.LookRotation(f));for(int j=0;j<3;j++)Person(site+f*R(-3,3)+right*R(5,9),j);}for(float d=80;d<560;d+=18){road.Sample(d,out var p,out var f);Vector3 r=Vector3.Cross(Vector3.up,f).normalized;for(int k=0;k<2;k++){Vector3 rock=p+r*R(65,100)+f*R(-9,9);rock.y=GroundHeight(rock.x,rock.z);if(rock.y<Sea-3||rock.y>19)continue;float h=R(2,6);art.Rock(ivory,rock+Vector3.up*h*.28f,new(R(3,7),h,R(3,7)),R(0,200),3,8);}}Sailboat(new Vector3(-80,Sea,-950),Quaternion.Euler(0,65,0),1.2f);Sailboat(new Vector3(380,Sea,-955),Quaternion.Euler(0,-24,0),.8f);Sailboat(new Vector3(-410,Sea,-880),Quaternion.Euler(0,125,0),.65f);}
 void PlantedStreets(){var road=Roads[2];for(float d=0;d<road.Length;d+=8){road.Sample(d,out var a,out var af);road.Sample(d+8,out var b,out var bf);Vector3 ar=Vector3.Cross(Vector3.up,af).normalized,br=Vector3.Cross(Vector3.up,bf).normalized;for(int sign=-1;sign<=1;sign+=2){Vector3 A=a+ar*(road.Width*.5f+.35f)*sign+Vector3.up*.07f,B=b+br*(road.Width*.5f+.35f)*sign+Vector3.up*.07f,C=b+br*(road.Width*.5f+10)*sign+Vector3.up*.07f,D=a+ar*(road.Width*.5f+10)*sign+Vector3.up*.07f;if(IsRoad((C+D)*.5f))continue;if(sign>0)art.Surface(pavers,A,B,C,D);else art.Surface(pavers,D,C,B,A);art.Beam(ivory,A+Vector3.up*.015f,B+Vector3.up*.015f,.3f,.20f);if(d%40<8){Vector3 p=a+ar*(road.Width*.5f+6)*sign;p.y=GroundHeight(p.x,p.z);art.Cylinder(ivory,p,p+Vector3.up*.65f,1.4f,1.6f,10);Shrub(p+Vector3.up*.65f,1.3f,true);if(d%120<8)Bench(p+af*3,Quaternion.LookRotation(af));}}}foreach(var site in occupied){if(site.z> -330||site.x<0)continue;for(int i=0;i<7;i++){Vector3 p=site+new Vector3(R(-13,13),0,R(-15,15));p.y=GroundHeight(p.x,p.z);if(!IsRoad(p))GrassClump(p,R(.4f,.8f));}}}
 void Shrub(Vector3 p,float scale,bool blossom){art.Rock(grass,p+Vector3.up*.38f*scale,new Vector3(.85f,.56f,.75f)*scale,R(0,999),2,6);if(blossom)for(int j=0;j<3;j++){Vector3 q=p+new Vector3(R(-.5f,.5f)*scale,R(.65f,.84f)*scale,R(-.5f,.5f)*scale);art.Rock(flowers,q,new Vector3(.16f,.10f,.15f)*scale,R(0,999),2,4);}}
 void GrassClump(Vector3 p,float scale){for(int i=0;i<5;i++){float a=R(0,Mathf.PI*2);Vector3 side=new Vector3(Mathf.Cos(a),0,Mathf.Sin(a))*scale*.08f,offset=new Vector3(R(-.28f,.28f),0,R(-.28f,.28f))*scale,tip=p+offset+new Vector3(Mathf.Sin(a)*.22f,R(.55f,1.1f),Mathf.Cos(a)*.22f)*scale;art.Tri(grass,p+offset-side,tip,p+offset+side);art.Tri(grass,p+offset+side,tip,p+offset-side);}}
 void NaturalGroves(){for(int i=0;i<92;i++){var road=Roads[i%2];road.Sample(R(0,road.Length),out var c,out var f);Vector3 side=Vector3.Cross(Vector3.up,f).normalized;c+=side*R(40,120)*(i%3==0?-1:1);c.y=GroundHeight(c.x,c.z);if(c.y<10||NearOccupied(c,38)||(c-FestivalCenter).sqrMagnitude<20000||c.z< -550&&c.x> -150)continue;for(int j=0;j<3;j++){Vector3 p=c+new Vector3(R(-13,13),0,R(-13,13));p.y=GroundHeight(p.x,p.z);if(Nearest(p.x,p.z,out _,out var w)>w*.5f+19&&p.y>8)Pine(p,R(6,11));}for(int j=0;j<8;j++){Vector3 p=c+new Vector3(R(-18,18),0,R(-18,18));p.y=GroundHeight(p.x,p.z);if(Nearest(p.x,p.z,out _,out var w)>w*.5f+8&&p.y>4){if(j<5)Shrub(p,R(.8f,2),j==0);else art.Rock(stone,p+Vector3.up*.65f,new(R(1,2.1f),R(.7f,1.9f),R(1,2.1f)),R(0,500),2,7);}}}for(int i=0;i<2100;i++){var road=Roads[i%3];road.Sample(R(0,road.Length),out var p,out var f);p+=Vector3.Cross(Vector3.up,f).normalized*R(road.Width*.5f+5,road.Width*.5f+36)*(i%2==0?1:-1);p.y=GroundHeight(p.x,p.z);if(p.y<1||NearOccupied(p,15)||(p-FestivalCenter).sqrMagnitude<1600||Nearest(p.x,p.z,out _,out var w)<w*.5f+4)continue;GrassClump(p,R(.35f,1.1f));if(i%4==0)Shrub(p,R(.6f,1.3f),i%8==0);}}
 void Sailboat(Vector3 p,Quaternion q,float scale){Vector3 P(float x,float y,float z)=>p+q*new Vector3(x,y,z)*scale;art.Quad(ivory,P(-2,.6f,-5),P(-1.6f,1.4f,-5),P(0,1.6f,7),P(0,-.7f,4));art.Quad(ivory,P(0,-.7f,4),P(0,1.6f,7),P(1.6f,1.4f,-5),P(2,.6f,-5));art.Quad(wood,P(-1.6f,1.4f,-5),P(0,1.6f,7),P(1.6f,1.4f,-5),P(0,1.4f,-5));art.Beam(metal,P(0,1,0),P(0,15,0),.10f*scale);art.Tri(ivory,P(.05f,14.6f,.1f),P(.05f,2,-.1f),P(.05f,2,-6.2f));art.Tri(ivory,P(.05f,14.6f,.1f),P(.05f,2,-6.2f),P(.05f,2,-.1f));art.Tri(teal,P(0,13.5f,.3f),P(0,2,6),P(0,2,.3f));art.Tri(teal,P(0,13.5f,.3f),P(0,2,.3f),P(0,2,6));}
 void Wilderness(){for(int i=0;i<1100;i++){float x=R(-1120,1120),z=R(-1070,1070);Vector3 p=OnGround(x,z);float d=Nearest(x,z,out _,out float w);if(p.y<1.5f||d<w*.5f+16||NearOccupied(p,22)||(p-FestivalCenter).sqrMagnitude<15000)continue;float h=R(.7f,3);if(i<560&&p.y>11&&p.y<125){if(random.NextDouble()<.69)Pine(p,R(7,12));else art.Rock(leafLight,p+Vector3.up*.55f,new(R(1.4f,2.6f),1.3f,R(1.4f,2.6f)),R(0,400),2,6);}else art.Rock(p.y<18?ivory:stone,p+Vector3.up*h*.4f,new(R(1.1f,3.6f),h,R(1.1f,3.6f)),R(0,500),3,7);}for(int i=0;i<95;i++){float a=R(0,Mathf.PI*2),r=R(990,1140);Vector3 p=OnGround(Mathf.Cos(a)*r,Mathf.Sin(a)*r);if(p.y<Sea-2||p.y>16)continue;art.Rock(ivory,p+Vector3.up*R(2,5),new(R(4,11),R(6,17),R(4,11)),R(0,300),4,8);}for(int i=0;i<22;i++){float x=R(-760,760),z=R(-700,700);Vector3 p=OnGround(x,z);if(p.y<10||NearOccupied(p,50)||Nearest(x,z,out _,out float w)<w*.5f+60||(p-FestivalCenter).sqrMagnitude<15000)continue;Building(p,Quaternion.Euler(0,R(0,360),0),R(9,15),R(9,14),I(1,3),I(0,5));occupied.Add(p);for(int t=0;t<3;t++){Vector3 tree=p+new Vector3(R(-24,24),0,R(12,23));tree.y=GroundHeight(tree.x,tree.z);Pine(tree,R(7,10));}}}
}
public sealed class SunwardWaterMotion:MonoBehaviour {Material water;void Start(){water=GetComponent<MeshRenderer>().material;}void Update(){water.mainTextureOffset=new Vector2(Time.time*.0007f,Time.time*.00033f);}}
